"""Bound painted member boxes as well as their visible text."""
JS=r'''let painted_outside=[];for(let e of root.querySelectorAll('.parts,.side,.from,.to,.node,.spoke,.ring,.level,.tile,.cell,.layer,.step,.stop,.plan,.person,.pan,.core,.seat,.set')){let st=getComputedStyle(e);if(st.display==='none'||st.visibility==='hidden'||parseFloat(st.opacity)===0)continue;let r=e.getBoundingClientRect();if(r.width<1||r.height<1)continue;let painted=rgba(st.backgroundColor)[3]>0||st.backgroundImage!=='none'||['Top','Right','Bottom','Left'].some(k=>parseFloat(st['border'+k+'Width'])>0&&st['border'+k+'Style']!=='none'&&rgba(st['border'+k+'Color'])[3]>0);if(!painted)continue;let owner=(e.hasAttribute('data-el')?e.parentElement.closest('[data-el]'):e.closest('[data-el]'))||root,b=owner.getBoundingClientRect();if(r.left<b.left-1||r.right>b.right+1||r.top<b.top-1||r.bottom>b.bottom+1||r.left<frame.left-1||r.right>frame.right+1||r.top<frame.top-1||r.bottom>frame.bottom+1)painted_outside.push({member:e.className,rect:[r.x,r.y,r.width,r.height],owner:owner.dataset.el||owner.className,ownerRect:[b.x,b.y,b.width,b.height]})}'''
